css:
.hrbp-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.hrbp-sim-container * {
    box-sizing: border-box;
}

.hrbp-sim-container .hrbp-sim-header {
    background: #1a2744;
    color: #ffffff;
    padding: 28px 32px;
    margin-bottom: 24px;
    border-left: 4px solid #c8a046;
    border-radius: 2px;
}
.hrbp-sim-container .hrbp-sim-header-eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.7rem;
    color: #c8a046;
    margin-bottom: 10px;
    font-weight: 600;
}
.hrbp-sim-container .hrbp-sim-header h1 {
    font-size: 1.7rem;
    font-weight: 600;
    margin: 0 0 8px 0;
    letter-spacing: -0.01em;
}
.hrbp-sim-container .hrbp-sim-header-sub {
    font-size: 0.95rem;
    color: #c2cad6;
    max-width: 720px;
    line-height: 1.5;
    margin-bottom: 14px;
}
.hrbp-sim-container .hrbp-sim-period-counter {
    display: inline-block;
    margin-top: 6px;
    padding: 6px 14px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(200,160,70,0.4);
    border-radius: 2px;
    font-size: 0.8rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}
.hrbp-sim-container .hrbp-sim-period-counter strong {
    color: #c8a046;
    font-weight: 700;
    margin: 0 4px;
}

.hrbp-sim-container .hrbp-sim-status-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.hrbp-sim-container .hrbp-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 18px 20px;
    border-radius: 2px;
    border-top: 3px solid #3a5078;
    transition: box-shadow 0.2s ease;
}
.hrbp-sim-container .hrbp-sim-kpi-card:hover {
    box-shadow: 0 4px 12px rgba(26,39,68,0.08);
}
.hrbp-sim-container .hrbp-sim-kpi-primary {
    border-top-color: #c8a046;
    background: linear-gradient(180deg, #ffffff 0%, #fdf8ed 100%);
}
.hrbp-sim-container .hrbp-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #6b7888;
    font-weight: 600;
    margin-bottom: 8px;
}
.hrbp-sim-container .hrbp-sim-kpi-value {
    font-size: 2.1rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.hrbp-sim-container .hrbp-sim-kpi-primary .hrbp-sim-kpi-value {
    color: #8a6a20;
}
.hrbp-sim-container .hrbp-sim-kpi-foot {
    font-size: 0.72rem;
    color: #8a93a3;
    margin-top: 6px;
    line-height: 1.3;
}

.hrbp-sim-container .hrbp-sim-briefing-zone {
    margin-bottom: 22px;
}
.hrbp-sim-container .hrbp-sim-round-panel {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 26px 30px;
    border-radius: 2px;
    border-left: 4px solid #1a2744;
}
.hrbp-sim-container .hrbp-sim-round-tag {
    display: inline-block;
    background: #1a2744;
    color: #c8a046;
    padding: 4px 12px;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 12px;
    font-weight: 600;
}
.hrbp-sim-container .hrbp-sim-round-panel h2 {
    font-size: 1.25rem;
    font-weight: 600;
    color: #1a2744;
    margin: 0 0 14px 0;
}
.hrbp-sim-container .hrbp-sim-brief {
    color: #3d4858;
    font-size: 0.95rem;
    line-height: 1.6;
    margin-bottom: 16px;
}
.hrbp-sim-container .hrbp-sim-anchor-box {
    background: #f8f5ec;
    border-left: 3px solid #c8a046;
    padding: 12px 16px;
    border-radius: 2px;
}
.hrbp-sim-container .hrbp-sim-anchor-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #8a6a20;
    font-weight: 600;
    margin-bottom: 4px;
}
.hrbp-sim-container .hrbp-sim-anchor-text {
    font-size: 0.85rem;
    color: #5a4a20;
    font-style: italic;
}

.hrbp-sim-container .hrbp-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 26px 30px;
    margin-top: 22px;
    margin-bottom: 28px;
    border-radius: 2px;
}
.hrbp-sim-container .hrbp-sim-controls-head {
    border-bottom: 1px solid #e6e9ee;
    padding-bottom: 14px;
    margin-bottom: 18px;
}
.hrbp-sim-container .hrbp-sim-controls-head h3 {
    font-size: 1rem;
    font-weight: 600;
    color: #1a2744;
    margin: 0 0 4px 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.hrbp-sim-container .hrbp-sim-controls-sub {
    font-size: 0.85rem;
    color: #6b7888;
}
.hrbp-sim-container .hrbp-sim-decisions {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 18px;
    margin-bottom: 20px;
}
.hrbp-sim-container .hrbp-sim-form-group {
    display: flex;
    flex-direction: column;
}
.hrbp-sim-container .hrbp-sim-form-group label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.hrbp-sim-container .hrbp-sim-form-group select,
.hrbp-sim-container .hrbp-sim-form-group input {
    background: #ffffff;
    border: 1px solid #c2cad6;
    color: #1a2744;
    border-radius: 2px;
    padding: 9px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
}
.hrbp-sim-container .hrbp-sim-form-group select:focus,
.hrbp-sim-container .hrbp-sim-form-group input:focus {
    border-color: #c8a046;
    outline: none;
    box-shadow: 0 0 0 2px rgba(200,160,70,0.18);
}
.hrbp-sim-container .hrbp-sim-form-group select option {
    background: #ffffff;
    color: #1a2744;
}

.hrbp-sim-container .hrbp-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
    border-top: 1px solid #e6e9ee;
    padding-top: 18px;
}
.hrbp-sim-container .hrbp-sim-actions .btn {
    border-radius: 2px;
    padding: 10px 22px;
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.hrbp-sim-container .hrbp-sim-actions .btn-primary {
    background: #1a2744;
    border: 1px solid #1a2744;
    color: #ffffff;
}
.hrbp-sim-container .hrbp-sim-actions .btn-primary:hover {
    background: #c8a046;
    border-color: #c8a046;
    color: #1a2744;
}
.hrbp-sim-container .hrbp-sim-actions .btn-outline-secondary {
    background: #ffffff;
    border: 1px solid #c2cad6;
    color: #6b7888;
}
.hrbp-sim-container .hrbp-sim-actions .btn-outline-secondary:hover {
    background: #f4f5f7;
    color: #1a2744;
    border-color: #1a2744;
}

.hrbp-sim-container .hrbp-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
}
.hrbp-sim-container .hrbp-sim-chart-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 22px;
    border-radius: 2px;
    height: 320px;
    position: relative;
}

.hrbp-sim-container .hrbp-sim-history {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 22px 26px;
    border-radius: 2px;
    margin-bottom: 22px;
}
.hrbp-sim-container .hrbp-sim-history h3 {
    font-size: 0.85rem;
    font-weight: 600;
    color: #1a2744;
    margin: 0 0 12px 0;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.hrbp-sim-container .hrbp-sim-history table {
    width: 100%;
    font-size: 0.88rem;
    color: #1a2744;
    margin-bottom: 0;
}
.hrbp-sim-container .hrbp-sim-history table thead th {
    background: #1a2744;
    color: #c8a046;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.72rem;
    font-weight: 600;
    border: none;
    padding: 10px 12px;
}
.hrbp-sim-container .hrbp-sim-history table tbody td {
    padding: 9px 12px;
    border-top: 1px solid #e6e9ee;
}
.hrbp-sim-container .hrbp-sim-history table tbody tr:hover {
    background: #fdf8ed;
}

.hrbp-sim-container .hrbp-sim-footnote {
    font-size: 0.72rem;
    color: #8a93a3;
    text-align: center;
    padding: 14px 8px;
    border-top: 1px solid #e6e9ee;
    letter-spacing: 0.04em;
}

@media (max-width: 768px) {
    .hrbp-sim-container { padding: 16px; }
    .hrbp-sim-container .hrbp-sim-header { padding: 20px; }
    .hrbp-sim-container .hrbp-sim-header h1 { font-size: 1.3rem; }
    .hrbp-sim-container .hrbp-sim-charts { grid-template-columns: 1fr; }
    .hrbp-sim-container .hrbp-sim-decisions { grid-template-columns: 1fr; }
    .hrbp-sim-container .hrbp-sim-kpi-value { font-size: 1.6rem; }
    .hrbp-sim-container .hrbp-sim-round-panel { padding: 18px; }
}


/* FIX v1.1.0 - completion / week-in-review screen */
.hrbp-sim-completion { padding: 8px 4px; text-align: center; }
.hrbp-sim-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #6b7280; margin-bottom: 6px; }
.hrbp-sim-completion-verdict { font-size: 24px; font-weight: 700; color: #111827; margin-bottom: 14px; }
.hrbp-sim-completion-score { display: inline-flex; align-items: baseline; gap: 8px; padding: 8px 16px; background: #f3f4f6; border-radius: 8px; margin-bottom: 18px; }
.hrbp-sim-completion-score span { font-size: 13px; color: #6b7280; }
.hrbp-sim-completion-score strong { font-size: 20px; color: #111827; }
.hrbp-sim-completion-insights-heading { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: #6b7280; margin-bottom: 8px; }
.hrbp-sim-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 640px; text-align: left; }
.hrbp-sim-completion-insights li { padding: 10px 14px; margin-bottom: 8px; background: #f9fafb; border-left: 3px solid #7c3aed; border-radius: 4px; color: #1f2937; font-size: 14px; }

