(function() {
    'use strict';

    class InclusiveManagerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Inclusive Manager — DEI in Daily Decisions';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    defensibility: 0,
                    documentation: 0,
                    fairnessByDesign: 0,
                    restraint: 0,
                    compositeScore: 0,
                    compositeHistory: [],
                    defensibilityHistory: [],
                    documentationHistory: [],
                    fairnessHistory: [],
                    restraintHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 50);
        }

        _getFieldsForRound(period) {
            if (period === 1) return ['sundayResponse', 'meetingOpening', 'ratingMechanic', 'dissentProtocol'];
            if (period === 2) return ['hirePosition', 'hireFramework', 'equalityPlanLead', 'mckinseyCase'];
            return ['docFormat', 'legalPathways', 'escalation', 'worksCouncil'];
        }

        _scoreMap() {
            return {
                sundayResponse:   { defer: 2, reassure: 1, substantive: 4 },
                meetingOpening:   { moralistic: 1, procedural: 2, pattern_via_protocol: 4 },
                ratingMechanic:   { aggregate: 1, joint: 3, criterion: 4 },
                dissentProtocol:  { majority: 1, consensus: 2, documented: 4 },
                hirePosition:     { veto: 1, approve: 2, install_framework: 4 },
                hireFramework:    { redo_loop: 2, re_score: 3, structured_panel_doc: 4 },
                equalityPlanLead: { open_with: 1, omit: 2, hold_reserve: 4 },
                mckinseyCase:     { open_with: 1, omit: 2, hold_defensive: 4 },
                docFormat:        { same_template: 1, case_specific: 2, works_council_defensible: 4 },
                legalPathways:    { blanket: 1, partial: 2, distinct_named: 4 },
                escalation:       { all_to_lucia: 1, none: 2, structural_brief: 4 },
                worksCouncil:     { none: 1, heads_up_only: 2, heads_up_plus_formal: 4 }
            };
        }

        _dimensionMap() {
            return {
                sundayResponse:   ['defensibility', 'restraint'],
                meetingOpening:   ['fairnessByDesign', 'restraint'],
                ratingMechanic:   ['fairnessByDesign', 'documentation'],
                dissentProtocol:  ['fairnessByDesign', 'documentation'],
                hirePosition:     ['restraint', 'defensibility'],
                hireFramework:    ['fairnessByDesign', 'defensibility'],
                equalityPlanLead: ['restraint', 'defensibility'],
                mckinseyCase:     ['restraint'],
                docFormat:        ['documentation', 'defensibility'],
                legalPathways:    ['documentation', 'defensibility'],
                escalation:       ['restraint', 'documentation'],
                worksCouncil:     ['documentation', 'defensibility']
            };
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;
            var fields = this._getFieldsForRound(period);
            for (var i = 0; i < fields.length; i++) {
                var el = document.getElementById(fields[i]);
                if (!el || !el.value) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('validation_warning'), 'warning'
                    );
                    return false;
                }
                decisions[fields[i]] = el.value;
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var fields = this._getFieldsForRound(period);
            var scoreMap = this._scoreMap();
            var dimMap = this._dimensionMap();

            var sums = { defensibility: 0, documentation: 0, fairnessByDesign: 0, restraint: 0 };
            var counts = { defensibility: 0, documentation: 0, fairnessByDesign: 0, restraint: 0 };

            for (var i = 0; i < fields.length; i++) {
                var f = fields[i];
                var choice = state.decisions[f];
                var score = (scoreMap[f] && scoreMap[f][choice]) ? scoreMap[f][choice] : 1;
                var pct = score * 25;
                var dims = dimMap[f] || [];
                for (var j = 0; j < dims.length; j++) {
                    sums[dims[j]] += pct;
                    counts[dims[j]] += 1;
                }
            }

            var def = counts.defensibility ? sums.defensibility / counts.defensibility : 0;
            var doc = counts.documentation ? sums.documentation / counts.documentation : 0;
            var fair = counts.fairnessByDesign ? sums.fairnessByDesign / counts.fairnessByDesign : 0;
            var rest = counts.restraint ? sums.restraint / counts.restraint : 0;

            state.domainState.defensibilityHistory.push(def);
            state.domainState.documentationHistory.push(doc);
            state.domainState.fairnessHistory.push(fair);
            state.domainState.restraintHistory.push(rest);

            var avg = function(arr) {
                if (!arr.length) return 0;
                var s = 0;
                for (var k = 0; k < arr.length; k++) s += arr[k];
                return s / arr.length;
            };
            state.domainState.defensibility = avg(state.domainState.defensibilityHistory);
            state.domainState.documentation = avg(state.domainState.documentationHistory);
            state.domainState.fairnessByDesign = avg(state.domainState.fairnessHistory);
            state.domainState.restraint = avg(state.domainState.restraintHistory);

            var composite = (state.domainState.defensibility * 0.3125)
                          + (state.domainState.documentation * 0.3125)
                          + (state.domainState.fairnessByDesign * 0.25)
                          + (state.domainState.restraint * 0.125);
            state.domainState.compositeScore = composite;
            state.domainState.compositeHistory.push(composite);

            // FIX v1.1.0 - expose score to the Express reporting layer
            // (express_resolveDomainScore reads performance.overallScore then top-level
            // `score`; original wrote only compositeScore, so the panel showed "-").
            // composite is 0-100 (dimension pct = scoreMap*25, weights sum to 1.0).
            state.domainState.score = composite;
            state.domainState.performance = { overallScore: composite, grade: this._grade(composite) };

            var roundLabel = window.mySimulation.t('round_short') + ' ' + period;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                roundLabel: roundLabel,
                defensibility: def,
                documentation: doc,
                fairnessByDesign: fair,
                restraint: rest,
                composite: composite
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('compositeDisplay', 'domainState.compositeScore',
                function(v) { return Math.round(v) + ' / 100'; });
            uiManager.bind('defensibilityDisplay', 'domainState.defensibility',
                function(v) { return Math.round(v); });
            uiManager.bind('documentationDisplay', 'domainState.documentation',
                function(v) { return Math.round(v); });
            uiManager.bind('fairnessDisplay', 'domainState.fairnessByDesign',
                function(v) { return Math.round(v); });
            uiManager.bind('restraintDisplay', 'domainState.restraint',
                function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                compositeChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Composite Score',
                            data: [],
                            borderColor: '#1a2744',
                            backgroundColor: 'rgba(200,160,70,0.18)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2,
                            pointBackgroundColor: '#c8a046',
                            pointBorderColor: '#1a2744',
                            pointRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Composite Score by Round' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { stepSize: 25 } }
                        }
                    }
                },
                dimensionsChart: {
                    type: 'bar',
                    data: {
                        labels: ['Defensibility', 'Documentation', 'Fairness-by-Design', 'Restraint'],
                        datasets: [{
                            label: 'Score',
                            data: [0, 0, 0, 0],
                            backgroundColor: ['#1a2744', '#3a5078', '#7a9bbd', '#c8a046'],
                            borderWidth: 0
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Performance Across Rubric Dimensions' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { stepSize: 25 } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.compositeHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                compositeChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.compositeHistory }]
                },
                dimensionsChart: {
                    labels: ['Defensibility', 'Documentation', 'Fairness-by-Design', 'Restraint'],
                    datasets: [{
                        data: [
                            state.domainState.defensibility,
                            state.domainState.documentation,
                            state.domainState.fairnessByDesign,
                            state.domainState.restraint
                        ]
                    }]
                }
            };
        }

        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
        }

        _grade(c) {
            if (c >= 80) return 'A';
            if (c >= 60) return 'B';
            if (c >= 40) return 'C';
            return 'D';
        }

        getPerformanceSummary(history) {
            var t = this._t();
            var periods = history ? history.length : 0;
            if (!periods) return { totalPeriods: 0 };
            var last = history[periods - 1];
            var composite = (last.results && last.results.composite) ? last.results.composite : 0;
            var bandKey = 'perf_beginning', ik = 'beg';
            if (composite >= 80) { bandKey = 'perf_distinguished'; ik = 'dist'; }
            else if (composite >= 60) { bandKey = 'perf_proficient'; ik = 'prof'; }
            else if (composite >= 40) { bandKey = 'perf_developing'; ik = 'dev'; }
            return {
                totalPeriods: periods,
                compositeScore: composite,
                overallScore: composite,
                defensibility: last.results.defensibility,
                documentation: last.results.documentation,
                fairnessByDesign: last.results.fairnessByDesign,
                restraint: last.results.restraint,
                band: t(bandKey),
                performance: t(bandKey),
                verdictKey: bandKey,
                insights: [t('insight_' + ik + '_1'), t('insight_' + ik + '_2')]
            };
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? Math.round(summary.overallScore)
                      : (typeof summary.compositeScore === 'number') ? Math.round(summary.compositeScore) : 0;
            var verdict = summary.performance || t('perf_beginning');
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="hrbp-sim-completion">'
                +   '<div class="hrbp-sim-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="hrbp-sim-completion-verdict">' + verdict + '</div>'
                +   '<div class="hrbp-sim-completion-score"><span>' + t('comp_score_label') + '</span>'
                +     '<strong>' + score + '/100</strong></div>'
                +   '<div class="hrbp-sim-completion-insights-heading">' + t('comp_insights_heading') + '</div>'
                +   '<ul class="hrbp-sim-completion-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.composite < 40) return window.mySimulation.t('hint_low');
            if (results.restraint < 50) return window.mySimulation.t('hint_restraint');
            if (results.documentation < 50) return window.mySimulation.t('hint_doc');
            if (results.fairnessByDesign < 50) return window.mySimulation.t('hint_fairness');
            if (results.composite >= 80) return window.mySimulation.t('hint_strong');
            return null;
        }

        getHistoryTableConfig() {
